INSERT INTO `activities` (`id`, `title`, `description`, `image`, `category`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 'ICT Reboot Ideathon', 'Solar Loop team achieved second place and received an internship at Orange Egypt.', 'uploads/activities1.jpg', 'Competition', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:34'),
	(2, 'National Skills 2025', 'Philip Emad qualified to represent Egypt in WorldSkills 2026 in Shanghai, China.', 'uploads/activities2.jpg', 'Award', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:34'),
	(3, 'Smart Glasses Innovation', 'Radwa Waref won 1st place for her smart glasses design for the visually impaired.', 'uploads/activities3.jpg', 'Innovation', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:34'),
	(4, 'Africa Tech Challenge', 'NCTU students won 2nd place in Mobile Applications among 12 African countries.', 'uploads/activities4.jpg', 'International', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:34'),
	(5, 'Biogas Project', 'Student team won 2nd place in Intelaqa 3 for converting organic waste into clean energy.', 'uploads/activities5.jpg', 'Sustainability', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(6, 'Best Eco-Friendly University', 'NCTU won 1st place in 2025 as the best green university in Egypt.', 'uploads/activities6.jpg', 'Achievement', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(7, 'Alamein Championship', 'Participation in football, padel, and volleyball in the New Alamein City sports event.', 'uploads/activities7.jpg', 'Sports', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(8, 'GEN Z - Fit Socket', 'Female team received 1M EGP funding for their AI-controlled prosthetic socket.', 'uploads/activities8.jpg', 'Innovation', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(9, 'Anti-Drug Marathon', 'Participation in the Administrative Capital marathon with over 1000 students.', 'uploads/activities9.jpg', 'Social', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(10, 'Startup Olympics 2024', 'Innovation projects in mechatronics and renewable energy presented in Helwan.', 'uploads/activities10.jpg', 'Entrepreneurship', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(11, 'Universities Youth Week', '600 students participated in the first tech youth week in Alexandria.', 'uploads/activities11.jpg', 'Community', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(12, 'Five-a-Side Football', 'NCTU football team represented the university in the Katameya championship.', 'uploads/activities12.jpg', 'Sports', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(13, 'National Kung Fu', 'Ziad Alaa (Bronze) and Radwa Sayed (Silver) in the national individual sports.', 'uploads/activities13.jpg', 'Sports', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(14, 'Bodybuilding Champ', 'Mohamed Yasser won 2nd place in Physique category at national level.', 'uploads/activities14.jpg', 'Sports', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(15, 'Hult Prize & Genius Forum', 'Students qualified for global finals in India for scientific innovations.', 'uploads/activities15.jpg', 'Achievement', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(16, 'Boxing Championship 1', 'Youssef Salah (2nd) and Rana Allam (3rd) in the universities boxing league.', 'uploads/activities16.jpg', 'Sports', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(17, 'Tennis & Padel', 'University secured 2nd place in national individual games for Tennis.', 'uploads/activities17.jpg', 'Sports', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(18, 'Boxing Championship 2', 'One of our female students achieved 1st place in the 5th Sector Boxing.', 'uploads/activities18.jpg', 'Sports', 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35');

