DELETE FROM `competitions`;
INSERT INTO `competitions` (`id`, `title`, `description`, `date`, `image`, `is_active`, `order`, `created_at`, `updated_at`) VALUES
	(1, 'NCTU Students Honored by AVIC INNO for Achieving Second Place in Mobile Applications', 'Under the patronage of Prof. Dr. Tarek Abdel Malak, NCTU students were honored by AVIC INNO for securing second place in mobile applications at the 10th Africa Technological Challenge.\n\nThe competition gathered 142 teams and 568 participants from across Africa under the slogan "Dream and Innovate Your Future." Participants underwent five weeks of intensive training by professional Chinese trainers.\n\nWinning Team:\n• Abdullah Ahmed Hassan Saad\n• Abdel Rahman Yahia Ibrahim\n• Demiana Samy Ounis\n\nAbdullah Ahmed Hassan Saad individually secured second place, earning a study opportunity in China. Since 2014, ATC has empowered over 1,000 African youth technicians.', 'September 28, 2025', 'uploads/CO.jpg', 1, 1, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(2, 'NCTU Hosts Ain Shams Racing Team', 'Under the patronage of Prof. Dr. Tarek Abdel Malak, New Cairo Technological University welcomed Ain Shams University Racing Team for technical collaboration.\n\nThe visit featured:\n• Workshop tours of NCTU\'s automotive facilities\n• Technical sessions between both racing teams\n• Project presentations on electric vehicles\n• Certificate ceremony honoring the visiting team\n\nThe event strengthened inter-university cooperation in automotive innovation and student development.', 'December 11, 2023', 'uploads/co2.jpg', 1, 2, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(3, 'A Year of Excellence & Innovation - NCTU Student Activities 2024/2025 Highlights', 'Under the patronage of Prof. Dr. Tarek Abdel Malak, New Cairo Technological University students achieved outstanding success in the 2024/2025 academic year.\n\nThe achievements included:\n• Award-winning innovations in Hult Prize and Gen Z competitions\n• International recognition through global conference participation\n• Sports excellence in design and athletic competitions\n• Specialized competition victories in PetroCamp and ministry contests\n• Student-led initiatives including Google Developer Group\n• National representation at Technology Universities Week\n\nThese accomplishments demonstrate NCTU\'s commitment to developing well-rounded technological leaders and innovators.', '2024/2025', 'uploads/co4.jpg', 1, 3, '2026-05-18 19:04:22', '2026-05-21 10:15:35'),
	(4, 'NCTU Wins First Place in Anti-Drug Awareness Campaign', 'Under the patronage of Prof. Dr. Mahmoud El-Sheikh, University President, and Prof. Dr. Tarek Abdel Malak Mikhail, Dean of the Faculty of Industrial Technology and Energy, New Cairo Technological University participated in a national anti-drug campaign.\n\nThe program included:\n• Leadership training for student volunteers\n• Technology projects promoting drug prevention\n• Awareness initiatives from the Addiction Prevention Fund\n• Sports competitions encouraging healthy lifestyles\n\nNCTU won first place in football during the camp, demonstrating the university\'s active role in student development and social responsibility.', 'August 8, 2023', 'uploads/co3.jpg', 1, 4, '2026-05-18 19:04:22', '2026-05-21 10:15:35');

