INSERT INTO `deans` (`id`, `full_name`, `title`, `position`, `faculty`, `image`, `welcome_text`, `education`, `experience`, `order`, `created_at`, `updated_at`) VALUES
	(1, 'Professor Dr. Walid Al-Khatam', 'Professor, Dr., PhD', 'Dean of the College of Industrial Technology and Energy', 'Faculty of Industrial and Energy Technology', 'uploads/1779178681_6a0c1cb95bf9e.png', 'We are pleased to welcome you to the Faculty of Industrial and Energy Technology, where we believe that education is the foundation for building a better future.\r\nOur faculty is committed to preparing highly qualified graduates who combine strong academic knowledge with practical skills that meet the needs of the labor market.\r\nWe strive to provide a modern and inspiring learning environment that encourages creativity and innovation.\r\nWe look forward to seeing our students become active partners in success and continuous development.', 'Ph.D. in Electrical Engineering, University of Waterloo, Canada – June 2005\r\nMaster\'s Degree in Electrical Engineering (Power and Electrical Machines), Ain Shams University, Egypt – 1996\r\nBachelor\'s Degree in Electrical Engineering (Power and Electrical Machines), Ain Shams University, Egypt – 1996', 'Professor, Department of Electrical Power and Machines Engineering, Faculty of Engineering, Ain Shams University, Egypt.\r\nConsultant for Electricity and Renewable Energy Development Programs in Egypt and Arab countries (since 2014).\r\nTechnical Consultant, Energy Excellence Center, Faculty of Engineering, Ain Shams University (2021-2023)\r\nVice Chairman, IEEE Power Engineering Society (PES) – Egypt Chapter (2020 – 2022)\r\nDirector, Energy Excellence Center, Faculty of Engineering, Ain Shams University (2019 - 2021)', 1, '2026-05-18 19:04:21', '2026-05-19 05:18:01'),
	(2, 'Professor Dr. Mohammed Fawzi Al-Sawda', 'Professor, Dr., PhD', 'Dean of the College of Applied Health Sciences', 'Faculty of Applied Health Sciences Technology', 'uploads/1780602035_6a21d4b3c677f.jpg', 'We are delighted to welcome you to the Faculty of Applied Health Sciences Technology, where we are dedicated to advancing education and training in the vital fields of health sciences.\r\nOur faculty aims to prepare competent graduates who combine scientific knowledge with practical skills to serve the community and meet the needs of the healthcare sector.\r\nWe are committed to providing a supportive and innovative learning environment that promotes excellence, ethics, and continuous improvement.', 'Under Construction', 'Under Construction', 2, '2026-05-18 19:04:21', '2026-06-04 16:40:35'),
	(3, 'Prof. Dr. Tamer Abouelnaga', 'Professor, Dr., PhD', 'Students Affairs Vice Dean of College of Industry and Energy Technology', 'College of Industry and Energy Technology', 'uploads/1780602100_6a21d4f440c35.png', 'The Students Affairs Vice Dean of the College of Industry and Energy Technology is committed to supporting students academically and personally. The office works to enhance student engagement, ensure academic guidance, and promote a positive learning environment.\r\nContinuous efforts are made to empower students and prepare them for professional success.', 'Ph.D. in Communications and Electronics Engineering. Ain Shams University, Egypt, 2012\r\nDissertation: Design and Implementation of Radio Frequency Identification (RFID) Antennas\r\n\r\nM.Sc. in Communications and Electronics Engineering. Ain Shams University, Egypt, 2007\r\nThesis: Field Theory Analysis of Microwave Dielectric Resonator Antennas\r\n\r\nB.Sc. in Electrical Engineering (Communications & Electronics).\r\nFaculty of Electronic Engineering, Menoufia University, Egypt, 1999 (Very Good with Honors)', 'Academic & Administrative Positions:\r\n\r\n• Students Affairs Vice Dean, College of Industry and Energy Technology, New Cairo Technological University (NCTU) (2022–2026)\r\n• Vice Dean for Community Service and Environmental Development, Higher Institute of Engineering and Technology, Kafr El‑Sheikh (2020–2022)\r\n• Students Affairs Vice Dean of Higher Institute of Engineering and Technology – Kafr Elsheikh City – Ministerial decision No. 1445- 23-4-2019\r\n• Professor: Electronics Research Institute- Ministry of Higher Education and Scientific Research (2-1-2024: Till now)\r\n• Associate Professor: Electronics Research Institute- Ministry of Higher Education and Scientific Research (14-3-2018: 1-1-2024)\r\n• Researcher: Electronics Research Institute- Ministry of Higher Education and Scientific Research (14-8-2012: 13-3-2018)\r\n• Assistant Researcher: Electronics Research Institute- Ministry of Higher Education and Scientific Research (10-9-2007: 13-8-2012)\r\n• Researcher Assistant: Electronics Research Institute- Ministry of Higher Education and Scientific Research (24-3-2001: 9-9-2007)\r\n• Associate Professor: Higher institute of engineering and technology - Ministry of Higher Education and Scientific Research (2018- 2022)\r\n\r\nTeaching Experience:\r\n\r\n2003–2014 | American University in Cairo (AUC).\r\nComputer Architecture (Course 339); Graduation Project – Cube Satellite (RF Transceiver & Antenna Design)\r\n\r\n2015–2022 | Higher Institute of Engineering and Technology, Kafr El-Sheikh.\r\nElectromagnetic Fields; Electronics; RF Power Amplifier; Antennas and Wave Propagation\r\n\r\n2021–2022 | Suez University, Faculty of Industrial Education.\r\nIntegrated Circuits Design; Electronic Circuits II\r\n\r\n2015–2016 | Akhbar El-Yom Academy\r\nElectronic Devices; Digital Circuits (I)\r\n\r\n2012–2014 | Al-Azhar University\r\nMicrowave Engineering; Electromagnetics\r\n\r\n2013–2015 | Integrated Thebes Institutes\r\nAcoustics; Antennas; Microwave Engineering; Electromagnetic Theory\r\n\r\n2019–2020 | Kafr Elsheikh University, Faculty of Engineering\r\nElectronic Engineering; Electromagnetic Fields\r\n\r\n2022–2026 | New Cairo Technological University, Faculty of Industry and Energy Technology\r\nProgramming using MATLAB; Embedded Systems; Analog and Digital Electronics\r\n\r\nThesis Supervisions:\r\n\r\nM.Sc. | Faculty of Engineering, Ain Shams University\r\nNovel Antenna Array System for Recent Radar Applications\r\n\r\nM.Sc. | Faculty of Engineering, Alexandria University\r\nBreast Cancer Early Detection\r\n\r\nM.Sc. | Faculty of Engineering, Alexandria University\r\nA Proposed Antennas Design and Implementation for Noninvasive Localized Breast Tumor Treatment using Microwave Hyperthermia\r\n\r\nPh.D. | Egypt-Japan University of Science and Technology (E-JUST)\r\nBreast Cancer Hyperthermia Treatment\r\n\r\nPh.D. | Faculty of Engineering, Aswan University\r\n5G Mobile Antennas\r\n\r\nPh.D. | Faculty of Engineering, Aswan University\r\nImplanted Antennas\r\n\r\nPh.D. | Faculty of Electronics Engineering, Menoufia University\r\nDesign of MIMO Antenna Array for 5G Systems\r\n\r\nPh.D. | Suez University\r\nEnhancing CMOS Power Amplifier Efficiency and Linearity Techniques for 5G Network Applications\r\n\r\nPh.D. | Faculty of Engineering, Ain Shams University\r\nMulti-static Ground-Based Arc Synthetic Aperture Radar (GB-A-SAR)\r\n\r\nPh.D. | Faculty of Engineering, Alexandria University\r\nBreast Tumor Diagnosis Using Microwave Imaging\r\n\r\nResearch Interests:\r\n\r\n• Microwave and RF Engineering\r\n• Antenna Design (UWB, MIMO, RFID, Biomedical Antennas)\r\n• Electromagnetic Modeling and Full‑Wave Analysis\r\n• Ground Penetrating Radar (GPR)\r\n• 5G and Sub‑6 GHz Wireless Systems\r\n• Biomedical Microwave Applications', 3, '2026-05-18 19:04:21', '2026-06-04 16:41:40');

