INSERT INTO `departments` (`id`, `name`, `slug`, `description`, `image`, `icon`, `order`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 'Mechatronics', 'mechatronics', 'Mechatronics Technology combines mechanical engineering, electronics, computer science, and control engineering.', 'uploads/1779180577_6a0c24216b80e.jpg', NULL, 1, 1, '2026-05-18 19:04:21', '2026-05-19 05:49:37'),
	(2, 'Auto-tronics', 'auto-tronics', 'Automotive Technology focuses on the design, development, and maintenance of automotive systems.', 'uploads/auto.jpeg', NULL, 2, 1, '2026-05-18 19:04:21', '2026-05-21 10:15:35'),
	(3, 'Information Technology', 'information-technology', 'Information Technology covers software development, networking, cybersecurity, and data management.', 'uploads/info.jpeg', NULL, 3, 1, '2026-05-18 19:04:21', '2026-05-21 10:15:35'),
	(4, 'Petroleum', 'petroleum', 'Petroleum Technology focuses on exploration, extraction, and processing of petroleum resources.', 'uploads/petro.jpeg', NULL, 4, 1, '2026-05-18 19:04:21', '2026-05-21 10:15:35'),
	(5, 'Renewable Energy', 'renewable-energy', 'Renewable Energy Technology covers solar, wind, and other sustainable energy sources.', 'uploads/renew.jpeg', NULL, 5, 1, '2026-05-18 19:04:21', '2026-05-21 10:15:35'),
	(6, 'Prosthetics', 'prosthetics', 'Prosthetics & Orthotics Technology focuses on designing and manufacturing artificial limbs and orthotic devices.', 'uploads/prothetic.jpeg', NULL, 6, 1, '2026-05-18 19:04:21', '2026-05-21 10:15:35');

