DELETE FROM `events`;
INSERT INTO `events` (`id`, `title`, `slug`, `category`, `description`, `event_date`, `location`, `image`, `link`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 'Annual Technology Innovation Fair 2025', 'tech-innovation-fair-2025', 'exhibition', 'Join us for the Annual Technology Innovation Fair showcasing student projects, research innovations, and industry partnerships. Experience cutting-edge technology demonstrations and network with industry leaders.', '2026-06-02 22:04:21', 'NCTU Main Campus, Exhibition Hall', 'uploads/1780597702_6a21c3c6532d2.jpg', 'http://127.0.0.1:8000/admin/events/1/edit', 1, 1, '2026-05-18 19:04:21', '2026-06-04 15:28:22'),
	(2, 'Robotics Workshop for Beginners', 'robotics-workshop-beginners', 'training', 'A hands-on workshop introducing students to the fundamentals of robotics, programming, and automation. Perfect for beginners interested in mechatronics and robotics engineering.', '2026-05-28 22:04:21', 'Mechatronics Lab, Building A', NULL, NULL, 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(3, 'Career Day: Meet Industry Professionals', 'career-day-2025', 'conference', 'Connect with leading companies in technology, engineering, and renewable energy sectors. Explore internship opportunities, full-time positions, and career guidance from industry experts.', '2026-06-07 22:04:21', 'NCTU Conference Center', NULL, NULL, 1, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(4, 'International Technology Conference 2026', NULL, NULL, 'Join us for the annual International Technology Conference featuring renowned speakers and cutting-edge research from various fields. Location: Main Auditorium, NCTU Campus. Date: May 15, 2026 at 9:00 AM.', NULL, NULL, NULL, '/conferences', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(5, 'Engineering Excellence Summit', NULL, NULL, 'A premier gathering of engineering professionals and students to explore innovations in civil, mechanical, and electrical engineering. Location: Conference Hall B. Date: June 20, 2026 at 10:00 AM.', NULL, NULL, NULL, '/conferences', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(6, 'Digital Transformation Forum', NULL, NULL, 'Explore the future of digital transformation in education and industry. Learn about AI, machine learning, and how technology is reshaping our world. Location: Innovation Center. Date: July 10, 2026 at 11:00 AM.', NULL, NULL, NULL, '/conferences', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(7, 'Professional Development Workshop Series', NULL, NULL, 'Comprehensive training sessions designed to enhance professional skills for students and faculty members. Topics include leadership, communication, and project management. Location: Training Center, Building C. Date: May 25, 2026 at 2:00 PM.', NULL, NULL, NULL, '/trainings-events', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(8, 'Advanced Programming Bootcamp', NULL, NULL, 'Intensive hands-on training in modern programming languages and frameworks. Learn Python, JavaScript, React, and Node.js from industry professionals. Location: Computer Lab 3. Date: June 5, 2026 at 9:00 AM.', NULL, NULL, NULL, '/trainings-events', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(9, 'Research Methodology Training', NULL, NULL, 'Learn essential research skills including literature review, data collection, analysis techniques, and academic writing. Ideal for graduate students and faculty. Location: Research Center. Date: June 15, 2026 at 1:00 PM.', NULL, NULL, NULL, '/trainings-events', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(10, 'Innovation & Technology Exhibition 2026', NULL, NULL, 'Showcase of cutting-edge technology, art, and innovation featuring student and faculty creative work. Explore projects from robotics to sustainable design and digital art. Location: Exhibition Hall, Main Building. Date: May 30, 2026 at 10:00 AM.', NULL, NULL, NULL, '/exhibitions', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(11, 'Student Art & Design Showcase', NULL, NULL, 'Annual exhibition featuring creative works from our talented students. View paintings, sculptures, digital art, architectural models, and multimedia installations. Location: Art Gallery, Cultural Center. Date: June 12, 2026 at 11:00 AM.', NULL, NULL, NULL, '/exhibitions', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(12, 'Sustainable Engineering Solutions Expo', NULL, NULL, 'Exhibition highlighting sustainable engineering projects and green technology innovations. Discover how our students contribute to environmental sustainability. Location: Engineering Building Lobby. Date: July 5, 2026 at 9:00 AM.', NULL, NULL, NULL, '/exhibitions', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(13, 'Senior Capstone Project Presentations', NULL, NULL, 'Final year projects demonstrating innovation, research, and technical expertise. Students present capstone projects in engineering, computer science, business, and applied sciences. Location: Auditorium Complex. Date: June 1, 2026 at 9:00 AM.', NULL, NULL, NULL, '/graduation-projects', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(14, 'Engineering Design Projects Showcase', NULL, NULL, 'Explore innovative engineering solutions developed by graduating students. Projects include smart city applications, renewable energy systems, and IoT implementations. Location: Engineering Labs. Date: June 8, 2026 at 10:00 AM.', NULL, NULL, NULL, '/graduation-projects', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(15, 'Computer Science Final Projects Demo Day', NULL, NULL, 'Live demonstrations of software applications, mobile apps, AI systems, and web platforms developed by computer science graduates. Location: IT Building, Demo Lab. Date: June 18, 2026 at 2:00 PM.', NULL, NULL, NULL, '/graduation-projects', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(16, 'Annual Hackathon Challenge', NULL, NULL, '48-hour coding marathon where teams compete to build innovative software solutions. Academic, technical competitions for students to showcase their skills. Prizes for top three teams. Location: Innovation Hub. Date: May 20, 2026 at 8:00 AM.', NULL, NULL, NULL, '/competitions', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(17, 'Robotics Competition 2026', NULL, NULL, 'Students compete in designing and programming autonomous robots to complete challenging tasks. Categories include line following, maze solving, and object manipulation. Location: Robotics Lab. Date: June 25, 2026 at 10:00 AM.', NULL, NULL, NULL, '/competitions', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(18, 'Business Plan Competition', NULL, NULL, 'Entrepreneurship competition where student teams pitch their business ideas to a panel of investors and industry experts. Winners receive seed funding and mentorship. Location: Business School Auditorium. Date: July 15, 2026 at 1:00 PM.', NULL, NULL, NULL, '/competitions', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(19, 'Inter-University Sports Championship', NULL, NULL, 'Annual sports competition featuring football, basketball, volleyball, and athletics. NCTU teams compete against other universities in a week-long tournament. Location: Sports Complex. Date: May 10, 2026 at 8:00 AM.', NULL, NULL, NULL, '/competitions', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21');

