	(2, 'Shanxi University of Finance and Economics', 'The agreement facilitates faculty exchange, student exchange programs and development of technological education.', NULL, NULL, 2025, 1, 2, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(3, 'Jilin International Studies University', 'The cooperation aims to exchange expertise related to achieving international quality standards in higher education institutions.', NULL, NULL, 2025, 1, 3, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(4, 'Taiyuan University of Technology – China', 'The memorandum includes faculty exchange, research cooperation and joint training programs.', NULL, NULL, 2025, 1, 4, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(5, 'Beijing Youth Politics College', 'The agreement aims to exchange students and faculty members and organize short academic programs.', NULL, NULL, 2024, 1, 1, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(6, 'Shanghai University of Electric Power', 'The memorandum establishes a joint academic degree program in automation and artificial intelligence.', NULL, NULL, 2024, 1, 2, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(7, 'North China Electric Power University', 'The protocol promotes scientific cooperation through faculty exchange visits and joint workshops.', NULL, NULL, 2024, 1, 3, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(8, 'Higher Technical Institute – Italy', 'A quadrilateral memorandum between the university, Italian institute, Danieli Company and Don Bosco Institute.', NULL, NULL, 2024, 1, 4, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(9, 'Human Restart – Germany', 'The protocol supports international partnerships and provides employment opportunities for graduates.', NULL, NULL, 2024, 1, 5, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(10, 'University of Strathclyde', 'The agreement aims to develop curricula and establish training programs in prosthetics and orthotics.', NULL, NULL, 2022, 1, 1, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(11, 'Akdo4ren Renewable Energy Company', 'The protocol strengthens cooperation in renewable energy maintenance and training programs.', NULL, NULL, 2022, 1, 2, '2026-05-18 19:04:22', '2026-05-18 19:04:22');

