DELETE FROM `graduates`;
INSERT INTO `graduates` (`id`, `title`, `description`, `is_active`, `order`, `created_at`, `updated_at`, `image`) VALUES
	(1, 'Training of New Cairo Technological University Students at Petrojet', 'As part of its commitment to enhancing practical experience and aligning academic study with market needs, students from the Information and Communication Technology and New and Renewable Energy Technology programs at New Cairo Technological University completed field training at Petrojet from July 27 to August 7, 2025.\n\nThe training was held under the patronage of Prof. Dr. Tarek Abdel Malak, President of the University, and Prof. Dr. Walid El-Khatam, Dean of the Faculty of Industry and Energy Technology, and coordinated by Mr. Abdelrahman Omar, University Training Coordinator.\n\nThe program included hands-on sessions on network fundamentals, the company\'s technological infrastructure, and practical training on the SAP system used globally for resource and project management', 1, 1, '2026-05-18 19:04:21', '2026-05-21 10:15:35', NULL),
	(2, 'NCTU Wins Three Awards at the 3rd "Entlaqah" Competition', 'Under the patronage of Prof. Dr. Tarek Abdel Malak, President of New Cairo Technological University, and Prof. Dr. Walid El-Khatam, Dean of the Faculty of Industry and Energy Technology, NCTU students achieved remarkable success by winning three awards in the third edition of the "Entlaqah" competition, organized by the Higher Technological Institute in Beni Suef at the Egyptian Space Agency.\n\nThe university participated with seven innovative projects from the Mechatronics, Renewable Energy, and Autotronics programs, supervised by Dr. Shereef El Hosary and Dr. Bothaina Mahmoud Fouad, Head of the Entrepreneurship Club.', 1, 2, '2026-05-18 19:04:21', '2026-05-21 10:15:35', NULL),
	(3, 'NCTU Honors Students for Participation in ROV Submarine Competition', 'Under the patronage of Prof. Dr. Tarek Abdel Malak, President of New Cairo Technological University, and the university leadership, NCTU held a ceremony to honor its students for their outstanding participation in the ROV Underwater Robotics Project.\n\nThe competition, organized by the Arab Academy for Science, Technology & Maritime Transport under the title MATE ROV Egypt, aimed to promote innovation in underwater exploration technologies.\n\nThis recognition reflects the university\'s commitment to supporting creativity, research, and student excellence.', 1, 3, '2026-05-18 19:04:21', '2026-05-21 10:15:35', NULL),
	(4, 'Green Hydrogen Research Collaboration', 'A meeting was held under Professor Dr. Tarek Abdelmalak\'s patronage to launch student and postgraduate research projects, focusing on the production and industrial application of green hydrogen.', 1, 4, '2026-05-18 19:04:21', '2026-05-21 10:15:35', NULL),
	(5, 'NCTU Students Excel in Training Program with the Egyptian Drilling Company', 'Under the patronage of Prof. Dr. Tarek Abdel Malak, President of New Cairo Technological University, and in cooperation with the Ministry of Petroleum, Mineral Resources, and the Ministry of Labor, students and graduates of the Oil Production, Processing, and Transport Technology Program participated in a specialized training program organized by the Egyptian Drilling Company (EDC).\n\nThe program aimed to enhance technical and practical skills, preparing participants for real-world challenges in the energy sector.', 1, 5, '2026-05-18 19:04:22', '2026-05-21 10:15:35', NULL),
	(6, 'NCTU Students Honored by AVIC INNO for Excellence in Africa Technology Challenge', 'Students of New Cairo Technological University (NCTU) were honored by AVIC Innovation Holding Limited (AVIC INNO) after achieving second place in the Mobile Applications category at the Africa Technology Challenge (ATC) — Season 10.\n\nThe competition brought together 142 university teams and 568 participants from across Africa, showcasing innovation and excellence among young tech talents.', 1, 6, '2026-05-18 19:04:22', '2026-05-21 10:15:35', NULL),
	(7, 'NCTU Shines in the National Wushu Championship', 'New Cairo Technological University proudly participated in the National Wushu Championship, organized by the Ministry of Higher Education, where top athletes from Egyptian universities competed with great spirit and skill.\n\nZiad Alaa Mohamed won third place and the bronze medal,\nRadwa Sayed Abdelkarim achieved second place and the silver medal.\n\nNCTU congratulates its champions for their outstanding achievements and reaffirms its commitment to supporting talented students in all fields.', 1, 7, '2026-05-18 19:04:22', '2026-05-21 10:15:35', NULL),
	(8, 'NCT Students Shine in Kung Fu Competitions', 'Students of New Cairo Technological University participated in the national Kung Fu championships among Egyptian universities, showcasing outstanding performance and remarkable sportsmanship.\n\nThis participation reflects the university\'s commitment to supporting its students physically and mentally, fostering a spirit of discipline, perseverance, and national pride — in line with Egypt\'s vision of empowering youth and encouraging excellence in all fields.', 1, 8, '2026-05-18 19:04:22', '2026-05-21 10:15:35', NULL),
	(9, 'Active Student Participation in Sports and Cultural Events', 'NCTU students actively took part in a variety of sports competitions, including five-a-side football, padel tennis, beach volleyball, and marathon running, alongside cultural and entertainment activities that showcased their creativity and national pride.\n\nThis participation reflects the university\'s commitment to empowering students, enhancing their skills, and providing a well-rounded educational experience in line with Egypt\'s vision to build an innovative and aware generation.\n\nNCTU extends its appreciation to its talented students for their dedication and wishes them continued success and excellence.', 1, 9, '2026-05-18 19:04:22', '2026-05-21 10:15:35', NULL);

