INSERT INTO `news` (`id`, `title`, `slug`, `excerpt`, `content`, `image`, `published_at`, `is_featured`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 'NCTU Announces New Scholarship Program for 2025', 'nctu-scholarship-program-2025', 'New Cairo Technological University is proud to announce a comprehensive scholarship program for outstanding students in technological fields.', '<p>New Cairo Technological University is proud to announce a comprehensive scholarship program for outstanding students in technological fields. The program aims to support talented students pursuing careers in mechatronics, information technology, and renewable energy.</p>', NULL, '2026-05-16 22:04:21', 1, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(2, 'NCTU Partners with Leading Tech Companies', 'nctu-tech-partnerships', 'The university has signed partnership agreements with major technology companies to provide internship opportunities and hands-on training for students.', '<p>The university has signed partnership agreements with major technology companies to provide internship opportunities and hands-on training for students in various technological disciplines.</p>', NULL, '2026-05-13 22:04:21', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(3, 'Research Excellence: NCTU Faculty Wins National Award', 'nctu-research-award', 'Dr. Ahmed Hassan from the Renewable Energy Department has been awarded the National Research Excellence Award for his groundbreaking work in solar energy systems.', '<p>Dr. Ahmed Hassan from the Renewable Energy Department has been awarded the National Research Excellence Award for his groundbreaking work in solar energy systems and sustainable technology solutions.</p>', NULL, '2026-05-11 22:04:21', 0, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(4, 'test', 'test', 'test', 'ttttttttttttttttttttttttttt', NULL, '2026-06-06 00:00:00', 0, 1, '2026-05-19 05:58:19', '2026-05-19 05:58:19');

