INSERT INTO `page_sections` (`id`, `page_id`, `section_key`, `section_title`, `section_content`, `section_image`, `section_order`, `is_active`, `created_at`, `updated_at`) VALUES
	(1, 2, 'faq', 'What is New Cairo Technological University (NCTU)?', 'It\'s a public technological university in Egypt that offers advanced applied education, focusing on linking studies directly to the job market.', NULL, 1, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(2, 2, 'faq', 'How is it different from regular universities?', 'Education here is more practical and hands-on. It prepares students directly for the job market and accepts students after high school or diploma.', NULL, 2, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(3, 2, 'faq', 'What majors or programs are available?', 'Programs vary by year, but usually include: Mechatronics, Information Technology, New and Renewable Energy, Prosthetics Technology, Control and Monitoring Systems, Equipment Operation and Maintenance Technology.', NULL, 3, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(4, 2, 'faq', 'How many years is the study program?', 'It\'s a 4-year program divided into two stages: First 2 years: Higher Technological Diploma, Last 2 years: Technological Bachelor\'s Degree (with certain conditions).', NULL, 4, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(5, 2, 'faq', 'Is the Technological Bachelor\'s degree recognized?', 'Yes, it is officially recognized by the Supreme Council of Universities and is equivalent to any bachelor\'s degree from other universities. You can also pursue postgraduate studies.', NULL, 5, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(6, 2, 'faq', 'Is there practical training?', 'Yes, practical training is a key part of the program and takes place both inside the university and at companies/factories.', NULL, 6, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(7, 2, 'faq', 'Is it part of the national admission system (Thanaweya Amma)?', 'Yes, the university is included in the national coordination system, and admission depends on the yearly minimum grade requirements.', NULL, 7, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(8, 2, 'faq', 'Does the university accept diploma holders?', 'Yes, it accepts graduates of technical diplomas (3 or 5-year systems) and technical institutes, but applicants must pass entrance exams.', NULL, 8, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(9, 2, 'faq', 'Is there on-campus housing?', 'Currently, there\'s no dormitory, but there are nearby housing options in areas like New Cairo or Katameya.', NULL, 9, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(10, 2, 'faq', 'Are there tuition fees?', 'Yes, there are fees. They\'re slightly higher than traditional public universities, but still much cheaper than private universities.', NULL, 10, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21'),
	(11, 2, 'faq', 'What are the job opportunities after graduation from NCTU?', 'Graduates are qualified for technical and engineering-related jobs in both public and private sectors. The university focuses on practical skills, so students can work in industries like automation, IT, energy, manufacturing, or even start their own business.', NULL, 11, 1, '2026-05-18 19:04:21', '2026-05-18 19:04:21');

