INSERT INTO `president_contents` (`id`, `full_name`, `title`, `position`, `image`, `welcome_text`, `education`, `postdoctoral`, `administrative`, `created_at`, `updated_at`) VALUES
	(1, 'Professor Dr. Tarek Abdelmalak', 'Professor, Dr., PhD', 'President of New Cairo Technological University', 'uploads/1779179025_6a0c1e11af242.jpg', 'On behalf of all faculty members and their assistants at New Cairo Technological University (NCT), I warmly welcome you as new members of our university family.\r\nWe believe that true success is not limited to academics but also includes building character, developing skills, and broadening horizons.', 'PhD (Mechanical Power Engineering), Shanghai University, China – 2002\r\nMaster\'s Degree (Mechanical Power Engineering), Cairo University, Egypt – 1996\r\nBachelor\'s Degree (Mechanical Power Engineering), Menoufia University, Egypt – 1991', '2003-2005: Scientific mission at KAIST, South Korea\r\n2017: Short research visit at Kumamoto University, Japan', 'Consultant at Niaf Paper Products Company (2005-2006)\r\nConsultant at Ramen Paper Products Company (2008-2012)\r\nProject Manager for Training Centers – Funded by Korean Government (2015-2017)\r\nMember of the Advisory Committee at the Science and Technology Development Fund (STDF)\r\nHonored as one of the Top Ten Directors of Technological Education Centers in Africa by the African Union (2015)', '2026-05-18 19:04:21', '2026-05-19 05:23:45'),
	(2, 'Professor Dr. Tarek Abdelmalak', 'Professor', 'President of New Cairo Technological University', NULL, 'On behalf of all faculty members and their assistants at New Cairo Technological University (NCT), I warmly welcome you as new members of our university family.\nWe believe that true success is not limited to academics but also includes building character, developing skills, and broadening horizons.', 'PhD (Mechanical Power Engineering), Shanghai University, China – 2002\nMaster\'s Degree (Mechanical Power Engineering), Cairo University, Egypt – 1996\nBachelor\'s Degree (Mechanical Power Engineering), Menoufia University, Egypt – 1991', '2003-2005: Scientific mission at KAIST, South Korea\n2017: Short research visit at Kumamoto University, Japan', 'Consultant at Niaf Paper Products Company (2005-2006)\nConsultant at Ramen Paper Products Company (2008-2012)\nProject Manager for Training Centers – Funded by Korean Government (2015-2017)\nMember of the Advisory Committee at the Science and Technology Development Fund (STDF)\nHonored as one of the Top Ten Directors of Technological Education Centers in Africa by the African Union (2015)', '2026-05-18 19:04:21', '2026-05-18 19:04:21');

