	(1, 'NCTU Students Train at the Heart of Egypt\'s Oil Fields', 'Students from the Petroleum Production program completed their 2024/2025 summer training in the Eastern Desert and South Sinai in collaboration with EGPC.', NULL, NULL, NULL, NULL, 'EGPC', '2025-07-28', NULL, 'Eastern Desert and South Sinai', NULL, NULL, 'Technical', 1, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(2, 'Administrative Staff Training Program Launched', 'Specialized training for administrative staff focusing on technological and industrial advancements like SQL, ICDL, and Forms.', NULL, NULL, NULL, NULL, NULL, '2024-07-18', NULL, 'NCTU Campus', NULL, NULL, 'Professional Development', 1, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(3, 'NTCU and LONGi Partner for Solar Energy Training', 'A three-day program combining theory and practice in PV systems and solar panel maintenance under LONGi supervision.', NULL, NULL, NULL, NULL, 'LONGi', '2024-09-18', '2024-09-20', 'NCTU Campus', 24, NULL, 'Technical', 1, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(4, 'Mechatronics Students Summer Training at Qader Factory', 'Hands-on experience in automation control, mechanical systems, and electrical systems at the prestigious Qader Factory.', NULL, NULL, NULL, NULL, 'Qader Factory', '2025-07-21', NULL, 'Qader Factory', NULL, NULL, 'Technical', 1, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(5, 'Field Training Program in Autotronics at Arab Contractors', 'Field training for first-year students to expose them to real work environments and modern automotive industry systems.', NULL, NULL, NULL, NULL, 'Arab Contractors', '2026-03-05', NULL, 'Arab Contractors', NULL, NULL, 'Technical', 1, '2026-05-18 19:04:22', '2026-05-18 19:04:22'),
	(6, 'Free International Scholarship in Prosthetics', 'Collaboration for international accreditation in Prosthetics and Orthotics, aligning with Egypt\'s Vision 2030.', NULL, NULL, NULL, NULL, NULL, '2026-02-28', NULL, 'International', NULL, NULL, 'Professional Development', 1, '2026-05-18 19:04:22', '2026-05-18 19:04:22');

